namespace MoreSpace {
partial class MainWindow {
 TextBox updatesOutput=new TextBox(),updateId=new TextBox();
 void SetupUpdates(){var page=Page("Atualizações","Consulte atualizações pelo winget. A instalação é interativa: contratos, permissões e avisos continuam sob seu controle. A Microsoft Store é aberta separadamente.");var bar=new FlowLayoutPanel{Dock=DockStyle.Fill};bar.Controls.Add(Btn("Consultar winget",async delegate{if(busy||demoMode)return;Busy(true);cancel.Enabled=false;updatesOutput.Text="Consultando… O winget pode precisar configurar suas fontes na primeira execução.";try{updatesOutput.Text=await Task.Run(()=>AppManager.Run("if(-not(Get-Command winget.exe -ErrorAction SilentlyContinue)){throw 'winget não instalado. Instale o App Installer pela Microsoft Store.'}; & winget.exe upgrade --disable-interactivity 2>&1 | Out-String"));}catch(Exception ex){updatesOutput.Text=ex.Message;}finally{Busy(false);}}));bar.Controls.Add(Btn("Abrir atualizações da Store",delegate{OpenSettings("ms-windows-store://downloadsandupdates");}));updateId.Width=210;updateId.Margin=new Padding(6,8,8,0);bar.Controls.Add(updateId);bar.Controls.Add(Btn("Atualizar ID…",delegate{var id=updateId.Text.Trim();if(!Regex.IsMatch(id,@"^[A-Za-z0-9][A-Za-z0-9._-]{1,150}$")){MessageBox.Show(this,"Copie o ID exato da lista de atualizações (ex.: Microsoft.PowerToys).");return;}LaunchReviewed("Atualizar "+id,"winget.exe","upgrade --id "+id+" --exact --interactive",false);}));page.Controls.Add(bar,0,1);updatesOutput.Multiline=true;updatesOutput.ReadOnly=true;updatesOutput.ScrollBars=ScrollBars.Both;updatesOutput.WordWrap=false;updatesOutput.Dock=DockStyle.Fill;updatesOutput.Font=new Font("Consolas",10);updatesOutput.Text="Clique em Consultar winget. Depois copie o ID desejado no campo e use Atualizar ID.\r\nA consulta não instala atualizações.";page.Controls.Add(updatesOutput,0,2);page.Controls.Add(new Label{Dock=DockStyle.Fill,Text="A atualização é executada pelo winget oficial. Fontes não configuradas podem exigir abrir winget manualmente."},0,3);}
 void LaunchReviewed(string title,string file,string args,bool admin){if(busy||demoMode)return;if(MessageBox.Show(this,title+"?\r\n\r\nSerá aberta a ferramenta oficial do Windows. "+(admin?"O Windows solicitará permissão de administrador. ":"")+"Acompanhe o resultado na janela aberta.","Revisar ação",MessageBoxButtons.YesNo,MessageBoxIcon.Question,MessageBoxDefaultButton.Button2)!=DialogResult.Yes)return;try{Process.Start(new ProcessStartInfo(file,args){UseShellExecute=true,Verb=admin?"runas":""});Log("FERRAMENTA ABERTA "+title);status.Text="Ferramenta aberta; acompanhe a conclusão na janela do Windows.";}catch(Exception ex){MessageBox.Show(this,ex.Message,"Não foi possível abrir");}}
 void SetupMaintenance(){var page=Page("Revisão","Ferramentas oficiais, executadas somente quando você escolher. Nenhuma tarefa roda automaticamente e não há limpeza de Registro ou esvaziamento artificial de RAM.");var cards=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true};
  cards.Controls.Add(Btn("Limpar cache DNS…",delegate{LaunchReviewed("Limpar cache DNS",Path.Combine(Environment.SystemDirectory,"ipconfig.exe"),"/flushdns",true);}));
  cards.Controls.Add(Btn("Verificar disco (sem reparar)…",delegate{string drive=Path.GetPathRoot(Environment.SystemDirectory).TrimEnd('\\');LaunchReviewed("Verificar "+drive+" em modo de leitura",Path.Combine(Environment.SystemDirectory,"cmd.exe"),"/k chkdsk "+drive,true);}));
  cards.Controls.Add(Btn("Otimizar unidades…",delegate{LaunchReviewed("Abrir otimização de unidades",Path.Combine(Environment.SystemDirectory,"dfrgui.exe"),"",false);}));
  cards.Controls.Add(Btn("Configurar indexação da pesquisa…",delegate{LaunchReviewed("Abrir opções de indexação",Path.Combine(Environment.SystemDirectory,"control.exe"),"srchadmin.dll",false);}));
  cards.Controls.Add(Btn("Limpar componentes pelo DISM…",delegate{LaunchReviewed("Limpar componentes substituídos do Windows",Path.Combine(Environment.SystemDirectory,"cmd.exe"),"/k DISM.exe /Online /Cleanup-Image /StartComponentCleanup",true);}));
  cards.Controls.Add(Btn("Armazenamento do Windows",delegate{OpenSettings("ms-settings:storagesense");}));AddScheduleControls(cards);page.Controls.Add(cards,0,2);page.Controls.Add(new Label{Dock=DockStyle.Fill,Text="O +Espaço registra a abertura da ferramenta; a conclusão e eventuais reinicializações são informadas pelo Windows."},0,3);}
 ListView leftovers=new SmoothListView();
 void SetupLeftovers(){var page=Page("Dados de apps","Revise pastas de AppData. Ausência de um nome na lista de apps não prova que uma pasta é sobra. Nenhuma pasta vem marcada ou é apagada por inteiro.");var bar=new FlowLayoutPanel{Dock=DockStyle.Fill};bar.Controls.Add(Btn("Listar pastas de dados",delegate{if(demoMode)return;leftovers.Items.Clear();foreach(var root in new[]{Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData)})try{foreach(var d in new DirectoryInfo(root).EnumerateDirectories()){if((d.Attributes&FileAttributes.ReparsePoint)!=0||new[]{"Microsoft","Packages","Programs","Temp","MaisEspaco"}.Contains(d.Name,StringComparer.OrdinalIgnoreCase))continue;var row=new ListViewItem(new[]{d.Name,"Vínculo com app não verificado",d.FullName});row.Tag=d.FullName;leftovers.Items.Add(row);}}catch(Exception ex){Log(ex.Message);}}));bar.Controls.Add(Btn("Revisar arquivos da pasta…",async delegate{if(leftovers.SelectedItems.Count>0)await ReviewChartFiles((string)leftovers.SelectedItems[0].Tag);}));bar.Controls.Add(Btn("Abrir programas instalados",delegate{OpenSettings("ms-settings:appsfeatures");}));page.Controls.Add(bar,0,1);leftovers.Dock=DockStyle.Fill;leftovers.View=View.Details;leftovers.FullRowSelect=true;leftovers.MultiSelect=false;leftovers.Columns.Add("Pasta",200);leftovers.Columns.Add("Avaliação",250);leftovers.Columns.Add("Caminho",520);page.Controls.Add(leftovers,0,2);page.Controls.Add(new Label{Dock=DockStyle.Fill,Text="Dados de login, preferências e projetos podem estar aqui. Abra a pasta e confirme sua finalidade antes de remover arquivos."},0,3);}
}
